	const foo = () => {};
	inst.on('foo', foo);
	inst.on('foo', foo);
	inst.off('foo', foo);
	expect(events.get('foo')).to.deep.equal([foo]);
	inst.off('foo', foo);
	expect(events.get('foo')).to.deep.equal([]);
